cases=[]
def add(id,source,edit,mode,origin,expected):
 assert source!=edit
 cases.append(dict(id=id,family='flowchart',source=source,sourceSha256=source_sha(source),renderOptions={'graphLayout':{'backend':'elk',**({'quality':'balanced'} if mode=='balanced' else {})}},edit={'source':edit,'sourceSha256':source_sha(edit)},measurementOrigin=origin,expectedEvidence=expected))
for n,expect in [(4,'4-node Pareto winner; native paint passed'),(54,'LCG135 public improvement; native paint passed'),(62,'LCG139 retains unverified native paint; adverse status is not a success')]:
 c=qual(n);assert c['source']==control(n)['source']
 src=c['source']
 if n==4:edit=src.replace('A[One]','A[One edit]');id='winning-duplicate-return-balanced';origin='Exact retained public qualification kept/control-4; genuine node-label edit'
 else:
  seed=135 if n==54 else 139
  assert c['id']==f'generated-cyclic:{seed}'
  edit=src.replace(f'Node {seed}-0',f'Edited node {seed}-0');id=f'lcg-{seed}-balanced';origin=f'Exact source retained in public qualification kept/control-{n}; existing generatedFlowchartSamples lcg-v1 seed {seed}, not regenerated by another implementation; genuine node-label edit'
 add(id,src,edit,'balanced',origin,expect)
